import{I as e,P as t,Q as n,n as r}from"./chunks/framework.BmaFRZVf.js";var i=JSON.parse(`{"title":"Proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/README.md","filePath":"proposals/README.md"}`),a={name:`proposals/README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="proposals" tabindex="-1">Proposals <a class="header-anchor" href="#proposals" aria-label="Permalink to “Proposals”">​</a></h1><p>This directory holds one change record per file: what the change was, why it was made, and how it was reviewed. A completed proposal is history. Current requirements live in the specifications, policies, and decisions it changed; see <a href="./../guides/current-specifications">Keeping Current Specifications</a>.</p><p>Name each file <code>&lt;NNNN&gt;-&lt;slug&gt;.md</code>, using the next four-digit number and a kebab-case slug. Required frontmatter is <code>id: proposal.&lt;NNNN&gt;</code>, <code>title</code>, <code>authors</code> as a non-empty list, <code>status</code>, <code>pull-request</code>, and <code>supersedes</code>. Optional <code>issues</code> is a list of issue references or URLs. The normal lifecycle is <code>draft</code> → <code>awaiting-implementation</code> → <code>active-review</code> → <code>accepted</code> → <code>implemented</code>.</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th><th>Decided by</th><th>Phase</th></tr></thead><tbody><tr><td><code>draft</code></td><td>Being written and iterated on in the draft pull request. May carry <code>[NEEDS CLARIFICATION:</code>.</td><td>agent</td><td>2</td></tr><tr><td><code>awaiting-implementation</code></td><td>The human settled the proposal. Implementation is underway or not yet started.</td><td>human</td><td>3</td></tr><tr><td><code>active-review</code></td><td>First full pass at tests, guides and code exists; report posted and pull request marked ready.</td><td>agent</td><td>5</td></tr><tr><td><code>returned-for-revisions</code></td><td>The human requested changes. Back to implementation, or to the proposal if the design changed.</td><td>human</td><td>5 → 3 or 2</td></tr><tr><td><code>accepted</code></td><td>The human accepted the work. Vision update, merge and release are underway.</td><td>human</td><td>5</td></tr><tr><td><code>implemented</code></td><td>The accepted implementation and final records are committed in the feature pull request before merge. Merge and any required release remain separate.</td><td>agent</td><td>5</td></tr><tr><td><code>rejected</code></td><td>The human declined the change. Kept as record.</td><td>human</td><td>terminal</td></tr><tr><td><code>withdrawn</code></td><td>The author pulled it. Kept as record.</td><td>either</td><td>terminal</td></tr><tr><td><code>superseded</code></td><td>A later proposal replaced it.</td><td>either</td><td>terminal</td></tr></tbody></table><p><strong>Decided by</strong> is about judgement, not keystrokes. The human may ask the agent to make the edit — that is fine. What an agent must never do is decide on its own that a proposal is settled enough to implement, or that finished work is good enough to accept. An agent that can reach those two conclusions unaided is an agent approving its own work.</p><p>After acceptance and the vision update, the agent records <code>implemented</code> in the original feature pull request before merging it. This status does not claim that the pull request has merged or that a required release happened. The pull request records integration; keep any remaining delivery visible in the proposal or pull request until separately authorized and performed. A merge-only change needs no release.</p><p>A proposal stays <code>draft</code> for as long as it takes. It is published to the draft pull request as soon as there is something to react to, and the human edits it there — directly, or by asking for changes — until they are satisfied. Iteration is the normal case, not a sign of a bad first draft.</p><p>Proposals are kept after they close. When a later proposal replaces an earlier one as a change, it names it in <code>supersedes</code> and the earlier one becomes <code>superseded</code>. That relationship records how the changes were made; it does not say which requirements apply now.</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};